import requests, xml.etree.ElementTree as ET
u='10728379'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':u,'retmode':'xml'},timeout=20)
root=ET.fromstring(r.text)
for a in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(a.itertext()))
for a in root.findall('.//Abstract/AbstractText'): print('ABSTRACT:', a.attrib.get('Label',''), ''.join(a.itertext()))
for a in root.findall('.//Author'): print('AUTHOR:', ' '.join((a.findtext('ForeName',''),a.findtext('LastName',''))).strip())
print('JOURNAL:',root.findtext('.//Journal/Title'),'YEAR:',root.findtext('.//PubDate/Year'))
